cpp.setup:
auto* anchor = new fluent::basicinput::Button(QStringLiteral("New shortcuts"), %PARENT%);
anchor->setFixedSize(136, 32);
anchor->move(152, 129);
anchor->show();
auto* control = new fluent::dialogs_flyouts::TeachingTip(%PARENT%);
control->setAnimationEnabled(false);
control->setTarget(anchor);
control->setLightDismissConsumesPress(true);
control->setCardSize(QSize(268, 96));
auto* layout = new QVBoxLayout(control->contentHost());
layout->setContentsMargins(14, 10, 14, 10);
layout->setSpacing(4);
auto* header = new QHBoxLayout;
header->setSpacing(8);
auto* heading = new fluent::textfields::Label(QStringLiteral("Command palette"), control->contentHost());
heading->setFluentTypography(Typography::FontRole::BodyStrong);
header->addWidget(heading, 1);
auto* closeButton = new fluent::basicinput::Button(control->contentHost());
closeButton->setAccessibleName(QStringLiteral("Close tip"));
closeButton->setIconGlyph(Typography::Icons::ChromeClose);
closeButton->setFluentLayout(fluent::basicinput::Button::IconOnly);
closeButton->setFluentStyle(fluent::basicinput::Button::Subtle);
closeButton->setFixedSize(24, 24);
header->addWidget(closeButton);
layout->addLayout(header);
auto* body = new fluent::textfields::Label(QStringLiteral("Press Ctrl+K anywhere to jump to files or commands."), control->contentHost());
body->setWordWrap(true);
body->setTextColorRole(fluent::textfields::Label::TextColorRole::Secondary);
layout->addWidget(body);
QObject::connect(closeButton, &fluent::basicinput::Button::clicked, control, &fluent::dialogs_flyouts::TeachingTip::close);
QObject::connect(anchor, &fluent::basicinput::Button::clicked, control, &fluent::dialogs_flyouts::TeachingTip::open);
control->open();
